/** Loaded geometric port networks. The persisted network owns values and logical pending events. */
public final class WorldCircuits {
    public static final String ADAPTER="nomoregrids:circuit";public static final int MAX_NODES=256;
    private final WorldService service;private final ServerLevel level;private int networkCursor,controlCursor,groupCursor;
    private record Thermal(List<Long> changes,long until){}
    private final Map<UUID,Thermal> thermal=new HashMap<>();
    private final net.nicomar.nomoregrids.diagnostic.WeightedLru<BinaryData,SimulationSnapshot> decoded=new net.nicomar.nomoregrids.diagnostic.WeightedLru<>(4*1024*1024);
    private record Topology(UUID id,ResourceId source,GridPoint origin,int orientation,Map<String,String> properties){}
    private boolean observing;private final Map<UUID,Long> resumeAfter=new HashMap<>();
    private List<Topology> topology=List.of();private List<Graph> graphCache=List.of();
    private PieceIndex lastGraphIndex;private List<Graph> lastGraphs=List.of();
    private record SignalValue(long tick,int value){}
    private long cachedSignalGeneration=-1;private Map<UUID,SignalValue> signalValues;
    private SimulationSnapshot decode(BinaryData data)throws IOException{var cached=decoded.get(data);if(cached.isPresent())return cached.orElseThrow();var built=SimulationCodec.decode(data.copy());long weight=256L+data.size()*3L;for(var state:built.circuits().values())weight+=state.nodes().size()*128L+state.edges().size()*96L+state.pending().size()*80L;decoded.put(data,built,weight);return built;}
    public net.nicomar.nomoregrids.diagnostic.WeightedLru.Stats cacheStats(){return decoded.stats();}
    private record Port(UUID piece,Direction6 normal,SupportResolver.Patch area,boolean output,SignalNetwork.Input input,boolean lockOnly){}
    private record Input(UUID ghost,PieceRecord piece,Port port){}
    private record Graph(UUID id,List<PieceRecord> pieces,List<SignalNetwork.Node> nodes,List<SignalNetwork.Edge> edges,List<Input> inputs){}
    public WorldCircuits(WorldService service){this.service=service;this.level=service.level();}
    public static boolean piece(PieceRecord p){return p.adapterId().value().equals(ADAPTER);}
    public static boolean eligible(BlockState s){if(!BuiltInRegistries.BLOCK.getKey(s.getBlock()).getNamespace().equals("minecraft"))return false;return s.is(Blocks.REDSTONE_WIRE)||s.is(Blocks.REPEATER)||s.is(Blocks.COMPARATOR)||s.is(Blocks.REDSTONE_BLOCK)||s.is(Blocks.REDSTONE_TORCH)||s.is(Blocks.REDSTONE_WALL_TORCH)||s.is(Blocks.LEVER)||s.getBlock() instanceof ButtonBlock||s.getBlock() instanceof BasePressurePlateBlock;}
    public static PieceRecord capture(BlockState state,BlockGetter level,BlockPos at,UUID id){var source=new ResourceId(BuiltInRegistries.BLOCK.getKey(state.getBlock()).toString());var shape=NativeStates.boxes(state.getShape(level,at));var collision=NativeStates.boxes(state.getCollisionShape(level,at));return new PieceRecord(id,0,new ResourceId(ADAPTER),1,source,NativeStates.properties(state),new GridPoint(at.getX()*16L,at.getY()*16L,at.getZ()*16L),0,GridPoint.BLOCK_CENTER,new BoxGeometrySnapshot(shape,collision,shape),new NativeStateImage(source,NativeStates.properties(state)).encode(),BinaryData.EMPTY,BinaryData.EMPTY,Optional.empty(),Set.of());}
    public static BlockState placement(Block block,net.minecraft.world.item.context.BlockPlaceContext context){var state=block.getStateForPlacement(context);if(state!=null)return state;var props=new HashMap<>(NativeStates.properties(block.defaultBlockState()));if(props.containsKey("facing"))props.put("facing",context.getHorizontalDirection().getOpposite().getName());if(props.containsKey("face"))props.put("face",context.getClickedFace()==Direction.UP?"floor":context.getClickedFace()==Direction.DOWN?"ceiling":"wall");return NativeStates.resolve(new ResourceId(BuiltInRegistries.BLOCK.getKey(block).toString()),props);}
    private static SignalNetwork.Node node(PieceRecord p){String id=p.sourceBlockId().value();var kind=id.endsWith("redstone_wire")?SignalNetwork.Kind.DUST:id.endsWith("repeater")?SignalNetwork.Kind.REPEATER:id.endsWith("comparator")?SignalNetwork.Kind.COMPARATOR:id.contains("redstone_")&&id.endsWith("torch")?SignalNetwork.Kind.TORCH:SignalNetwork.Kind.SOURCE;return new SignalNetwork.Node(p.pieceId(),kind,kind==SignalNetwork.Kind.REPEATER?2*Integer.parseInt(p.sourceState().get("delay")):kind==SignalNetwork.Kind.COMPARATOR||kind==SignalNetwork.Kind.TORCH?2:0,"subtract".equals(p.sourceState().get("mode")));}
    private static List<Port> ports(PieceRecord p){var result=new ArrayList<Port>();var kind=node(p).kind();var facing=Direction6.valueOf(p.sourceState().getOrDefault("facing","north").toUpperCase(Locale.ROOT));
        if(kind==SignalNetwork.Kind.REPEATER||kind==SignalNetwork.Kind.COMPARATOR){for(var side:List.of(Direction6.NORTH,Direction6.SOUTH,Direction6.EAST,Direction6.WEST)){boolean output=side==facing.opposite();boolean rear=side==facing;var local=new SupportResolver.Patch(side,side.sign()>0?16:0,7,0,9,2);var area=SupportPatches.transform(local,p);result.add(new Port(p.pieceId(),area.normal(),area,output,rear?SignalNetwork.Input.REAR:SignalNetwork.Input.SIDE,!rear&&!output&&kind==SignalNetwork.Kind.REPEATER));}}
        else if(kind==SignalNetwork.Kind.DUST){for(var side:List.of(Direction6.NORTH,Direction6.SOUTH,Direction6.EAST,Direction6.WEST)){var area=SupportPatches.transform(new SupportResolver.Patch(side,side.sign()>0?16:0,7,0,9,2),p);result.add(new Port(p.pieceId(),area.normal(),area,true,SignalNetwork.Input.REAR,false));}}
        else{Direction6 anchor=Direction6.DOWN;if(p.sourceBlockId().value().contains("wall_torch")||"wall".equals(p.sourceState().get("face")))anchor=facing.opposite();else if("ceiling".equals(p.sourceState().get("face")))anchor=Direction6.UP;for(var side:Direction6.values()){boolean input=kind==SignalNetwork.Kind.TORCH&&side==anchor;var area=SupportPatches.transform(new SupportResolver.Patch(side,side.sign()>0?16:0,0,0,16,16),p);result.add(new Port(p.pieceId(),area.normal(),area,!input,SignalNetwork.Input.REAR,false));}}
        return result;
    }
    private record WirePlane(Direction6 normal,long plane){}
    private static WirePlane wirePlane(PieceRecord p){var base=SupportPatches.transform(new SupportResolver.Patch(Direction6.DOWN,0,0,0,16,16),p);return new WirePlane(base.normal(),base.plane());}
    private static boolean matches(Port a,Port b){return a.normal==b.normal.opposite()&&a.area.plane()==b.area.plane()&&Math.max(a.area.u0(),b.area.u0())<Math.min(a.area.u1(),b.area.u1())&&Math.max(a.area.v0(),b.area.v0())<Math.min(a.area.v1(),b.area.v1());}
    private static boolean receives(PieceRecord p,Port port){return node(p).kind()!=SignalNetwork.Kind.SOURCE&&(node(p).kind()==SignalNetwork.Kind.DUST||!port.output);}
    private List<Graph> graphs(PieceIndex index){if(index==lastGraphIndex)return lastGraphs;var result=buildGraphs(index);lastGraphIndex=index;lastGraphs=result;return result;}
    private List<Graph> buildGraphs(PieceIndex index){
        var pieces=index.ticked(ADAPTER);var key=pieces.stream().map(p->{var values=new HashMap<>(p.sourceState());for(String name:List.of("power","powered","lit","locked"))values.remove(name);return new Topology(p.pieceId(),p.sourceBlockId(),p.origin16(),p.orientation(),Map.copyOf(values));}).toList();if(key.equals(topology)&&!graphCache.isEmpty())return graphCache.stream().map(g->new Graph(g.id,g.pieces.stream().map(p->index.records().get(p.pieceId())).toList(),g.nodes,g.edges,g.inputs)).toList();var byId=new HashMap<UUID,PieceRecord>();var portMap=new HashMap<UUID,List<Port>>();for(var p:pieces){byId.put(p.pieceId(),p);portMap.put(p.pieceId(),ports(p));}var edges=new ArrayList<SignalNetwork.Edge>();var adjacency=new HashMap<UUID,Set<UUID>>();
        for(var p:pieces){var candidates=new HashSet<UUID>();for(var c:p.worldOccupation().cells(8))for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)candidates.addAll(index.at(new CellPos(c.x()+x,c.y()+y,c.z()+z)));for(var other:candidates){if(!byId.containsKey(other)||other.equals(p.pieceId()))continue;var q=byId.get(other);for(var a:portMap.get(p.pieceId()))if(a.output)for(var b:portMap.get(other))if(receives(q,b)&&matches(a,b)){
            if(b.lockOnly&&node(p).kind()!=SignalNetwork.Kind.REPEATER&&node(p).kind()!=SignalNetwork.Kind.COMPARATOR)continue;
            if(node(p).kind()==SignalNetwork.Kind.DUST&&node(q).kind()==SignalNetwork.Kind.DUST&&(!wirePlane(p).equals(wirePlane(q))))continue;
            edges.add(new SignalNetwork.Edge(p.pieceId(),other,b.input,node(q).kind()==SignalNetwork.Kind.DUST&&node(p).kind()==SignalNetwork.Kind.DUST?16:0));adjacency.computeIfAbsent(p.pieceId(),k->new HashSet<>()).add(other);adjacency.computeIfAbsent(other,k->new HashSet<>()).add(p.pieceId());
        }}}
        var seen=new HashSet<UUID>();var result=new ArrayList<Graph>();for(var start:pieces)if(seen.add(start.pieceId())){var ids=new TreeSet<UUID>();var pending=new ArrayDeque<UUID>();pending.add(start.pieceId());while(!pending.isEmpty()){var id=pending.removeFirst();ids.add(id);if(ids.size()>MAX_NODES)throw new IllegalArgumentException("COMPLEXITY_LIMIT: circuit network");for(var next:adjacency.getOrDefault(id,Set.of()))if(seen.add(next))pending.add(next);}var members=ids.stream().map(byId::get).toList();var nodes=new ArrayList<>(members.stream().map(WorldCircuits::node).toList());var links=new ArrayList<>(edges.stream().filter(e->ids.contains(e.from())&&ids.contains(e.to())).distinct().toList());var inputs=new ArrayList<Input>();for(var p:members)for(var port:portMap.get(p.pieceId()))if(receives(p,port)){var ghost=UUID.nameUUIDFromBytes((p.pieceId()+"|native|"+port.normal).getBytes(StandardCharsets.UTF_8));nodes.add(new SignalNetwork.Node(ghost,SignalNetwork.Kind.SOURCE,0,false));links.add(new SignalNetwork.Edge(ghost,p.pieceId(),port.input,0));inputs.add(new Input(ghost,p,port));}if(nodes.size()>65536)throw new IllegalArgumentException("COMPLEXITY_LIMIT: circuit ports");result.add(new Graph(ids.first(),members,nodes,links,inputs));}topology=key;graphCache=List.copyOf(result);return graphCache;
    }
    private void loadThermal(){thermal.clear();for(var e:service.effectsWithPrefix("circuit:thermal:").entrySet())if(e.getKey().startsWith("circuit:thermal:")){var json=JsonParser.parseString(new String(e.getValue().data().copy(),StandardCharsets.UTF_8)).getAsJsonObject();for(var row:json.entrySet()){var data=row.getValue().getAsJsonObject();var times=new ArrayList<Long>();for(var t:data.getAsJsonArray("changes"))times.add(t.getAsLong());if(times.size()>8)throw new IllegalArgumentException("INVALID_DATA: torch burnout");var state=new Thermal(List.copyOf(times),data.get("until").getAsLong());var id=UUID.fromString(row.getKey());var old=thermal.get(id);if(old==null||state.until>old.until||!state.changes.isEmpty()&&(old.changes.isEmpty()||state.changes.getLast()>old.changes.getLast()))thermal.put(id,state);}}}
    private void thermal(Graph graph,SignalNetwork network,Map<UUID,Integer> previous,List<OperationPlan.Effect> effects){boolean changed=false;long now=level.getGameTime();for(var p:graph.pieces)if(node(p).kind()==SignalNetwork.Kind.TORCH&&previous.getOrDefault(p.pieceId(),0)>0&&network.value(p.pieceId())==0){var old=thermal.getOrDefault(p.pieceId(),new Thermal(List.of(),0));var times=new ArrayList<>(old.changes.stream().filter(t->now-t<=60).toList());times.add(now);long until=times.size()>=8?now+160:old.until;while(times.size()>8)times.removeFirst();thermal.put(p.pieceId(),new Thermal(List.copyOf(times),until));changed=true;}if(!changed)return;var json=new JsonObject();for(var p:graph.pieces){var state=thermal.get(p.pieceId());if(state==null)continue;var row=new JsonObject();var times=new JsonArray();state.changes.forEach(times::add);row.add("changes",times);row.addProperty("until",state.until);json.add(p.pieceId().toString(),row);}var key="circuit:thermal:"+graph.id;var old=service.effects().get(key);var owner=graph.pieces.getFirst().origin16().cell();effects.add(new OperationPlan.Effect(key,owner,Optional.ofNullable(old).map(WorldEffectStore.Value::data),Optional.of(new BinaryData(json.toString().getBytes(StandardCharsets.UTF_8))),old==null?owner:old.owner()));}
    private boolean discardable(BinaryData data){try{return decode(data).circuits().values().stream().flatMap(s->s.nodes().stream()).noneMatch(n->service.snapshot().records().containsKey(n.id()));}catch(IOException ex){return false;}}
    private boolean equivalent(BinaryData a,BinaryData b){try{var first=decode(a).circuits().values().iterator().next();var second=decode(b).circuits().values().iterator().next();return new HashSet<>(first.nodes()).equals(new HashSet<>(second.nodes()))&&new HashSet<>(first.edges()).equals(new HashSet<>(second.edges()))&&first.values().equals(second.values())&&first.sources().equals(second.sources())&&first.pending().equals(second.pending());}catch(IOException ex){throw new IllegalArgumentException("INVALID_DATA: circuit checkpoint",ex);}}
    public int value(PieceRecord p){
        if(cachedSignalGeneration!=service.signalGeneration())rebuildSignalValues();
        if(signalValues!=null){var value=signalValues.get(p.pieceId());return value==null?stateValue(p):value.value;}
        int result=stateValue(p);long tick=-1;for(var e:service.effectsWithPrefix("circuit:").entrySet())if(e.getKey().matches("circuit:[0-9a-f-]{36}"))try{for(var s:decode(e.getValue().data()).circuits().values())if(s.values().containsKey(p.pieceId())&&s.tick()>tick){tick=s.tick();result=s.values().get(p.pieceId());}}catch(IOException ex){throw new IllegalArgumentException("INVALID_DATA: circuit checkpoint",ex);}return result;
    }
    private void rebuildSignalValues(){
        var values=new HashMap<UUID,SignalValue>();for(var e:service.effectsWithPrefix("circuit:").entrySet())if(e.getKey().matches("circuit:[0-9a-f-]{36}"))try{
            for(var state:decode(e.getValue().data()).circuits().values())for(var value:state.values().entrySet()){
                var old=values.get(value.getKey());if(old==null||state.tick()>old.tick)values.put(value.getKey(),new SignalValue(state.tick(),value.getValue()));
                if(values.size()>65536){signalValues=null;cachedSignalGeneration=service.signalGeneration();return;}
            }
        }catch(IOException ex){throw new IllegalArgumentException("INVALID_DATA: circuit checkpoint",ex);}
        signalValues=Map.copyOf(values);cachedSignalGeneration=service.signalGeneration();
    }
    private SignalNetwork restored(Graph graph){var old=service.effects().get("circuit:"+graph.id);if(old==null)return inherited(graph);try{var state=decode(old.data()).circuits().get(graph.id);if(state==null)return inherited(graph);if(new HashSet<>(state.nodes()).equals(new HashSet<>(graph.nodes))&&new HashSet<>(state.edges()).equals(new HashSet<>(graph.edges)))return SignalNetwork.restored(state);
            return inherited(graph);
        }catch(IOException ex){throw new IllegalArgumentException("INVALID_DATA: circuit authority",ex);}}
    private SignalNetwork inherited(Graph g){var values=new HashMap<UUID,Integer>();var sources=new HashMap<UUID,Integer>();var pending=new HashMap<UUID,List<SignalNetwork.Pending>>();var descriptors=new HashMap<UUID,SignalNetwork.Node>();g.nodes.forEach(n->descriptors.put(n.id(),n));long tick=Math.max(0,level.getGameTime()-1);var logical=new HashMap<UUID,Long>();for(var e:service.effectsWithPrefix("circuit:").entrySet())if(e.getKey().matches("circuit:[0-9a-f-]{36}"))try{for(var state:decode(e.getValue().data()).circuits().values())for(var node:state.nodes())if(descriptors.containsKey(node.id())&&state.tick()>=logical.getOrDefault(node.id(),-1L)){logical.put(node.id(),state.tick());if(state.values().containsKey(node.id()))values.put(node.id(),state.values().get(node.id()));if(node.kind()==SignalNetwork.Kind.SOURCE&&state.sources().containsKey(node.id()))sources.put(node.id(),state.sources().get(node.id()));pending.put(node.id(),state.pending().stream().filter(event->event.id().equals(node.id())).toList());}}catch(IOException ex){throw new IllegalArgumentException("INVALID_DATA: inherited circuit",ex);}for(var p:g.pieces)values.putIfAbsent(p.pieceId(),seed(p));var events=pending.values().stream().flatMap(List::stream).toList();return SignalNetwork.restored(new SignalNetwork.Snapshot(tick,g.nodes,g.edges,values,sources,events));}
    private SignalNetwork initial(Graph graph){var values=new HashMap<UUID,Integer>();for(var p:graph.pieces)values.put(p.pieceId(),stateValue(p));return SignalNetwork.restored(new SignalNetwork.Snapshot(Math.max(0,level.getGameTime()-1),graph.nodes,graph.edges,values,Map.of(),List.of()));}
    private int seed(PieceRecord p){var seed=service.effects().get("circuit:seed:"+p.pieceId());return seed==null?stateValue(p):JsonParser.parseString(new String(seed.data().copy(),StandardCharsets.UTF_8)).getAsInt();}
    private static int stateValue(PieceRecord p){if(p.sourceBlockId().value().equals("minecraft:redstone_block"))return 15;if(p.sourceState().containsKey("power"))return Integer.parseInt(p.sourceState().get("power"));return Boolean.parseBoolean(p.sourceState().getOrDefault("powered",p.sourceState().getOrDefault("lit","false")))?15:0;}
    private int input(Input input){if(node(input.piece).kind()==SignalNetwork.Kind.TORCH&&thermal.getOrDefault(input.piece.pieceId(),new Thermal(List.of(),0)).until>level.getGameTime())return 15;int value=0;for(var c:SupportPatches.contactCells(input.port.area).cells(8)){var pos=WorldService.pos(c);if(!level.isLoaded(pos))continue;if(!service.snapshot().at(c).isEmpty()&&service.nativeProjection(c).isEmpty()){if(node(input.piece).kind()==SignalNetwork.Kind.COMPARATOR&&input.port.input==SignalNetwork.Input.REAR)for(var id:service.snapshot().at(c)){var p=service.snapshot().records().get(id);if(WorldRails.detector(p)){for(var output:ports(p))if(output.output&&matches(output,input.port))value=Math.max(value,WorldRails.analog(level,p));}if(WorldFunctionals.piece(p)&&NativeStates.resolve(p).hasAnalogOutputSignal()){boolean contact=SupportPatches.surfaces(p.worldOccupation()).stream().anyMatch(anchor->matches(new Port(p.pieceId(),anchor.normal(),anchor,true,SignalNetwork.Input.REAR,false),input.port));if(contact)value=Math.max(value,net.minecraft.world.inventory.AbstractContainerMenu.getRedstoneSignalFromContainer(service.functionals().detached(p)));}}continue;}var s=level.getBlockState(pos);if(s.getBlock() instanceof CompositeCellBlock)continue;if(input.port.lockOnly&&!(s.getBlock() instanceof DiodeBlock))continue;int n=node(input.piece).kind()==SignalNetwork.Kind.COMPARATOR&&input.port.input==SignalNetwork.Input.REAR&&s.hasAnalogOutputSignal()?s.getAnalogOutputSignal(level,pos,Direction.valueOf(input.port.normal.name())):level.getSignal(pos,Direction.valueOf(input.port.normal.name()));value=Math.max(value,n);}return value;}
    private BinaryData encode(Graph g,SignalNetwork network){try{return new BinaryData(SimulationCodec.encode(new SimulationSnapshot(g.pieces.getFirst().ownerSection(),0,Map.of(),Map.of(),Map.of(),Map.of(g.id,network.snapshot()))));}catch(IOException ex){throw new IllegalArgumentException("COMPLEXITY_LIMIT: circuit checkpoint",ex);}}
    public OperationPlan prepare(OperationPlan plan){if(plan.changes().stream().noneMatch(c->c.before().filter(WorldCircuits::piece).isPresent()||c.after().filter(WorldCircuits::piece).isPresent()))return plan;var after=service.snapshot().changed(plan.changes().stream().map(OperationPlan.Change::indexChange).toList(),PieceIndex.Limits.DEFAULT);for(var graph:graphs(after))encode(graph,initial(graph));var effects=new ArrayList<>(plan.effects());for(var c:plan.changes()){
        if(c.after().isPresent()&&piece(c.after().orElseThrow())){var p=c.after().orElseThrow();if(c.before().isEmpty()&&node(p).kind()==SignalNetwork.Kind.COMPARATOR){var pos=WorldService.pos(c.nativeSource().orElse(p.origin16().cell()));var nativeBE=level.getBlockEntity(pos);if(nativeBE instanceof net.minecraft.world.level.block.entity.ComparatorBlockEntity comparator&&NativeStates.original(p).equals(level.getBlockState(pos))){var data=new BinaryData(Integer.toString(comparator.getOutputSignal()).getBytes(StandardCharsets.UTF_8));effects.add(new OperationPlan.Effect("circuit:seed:"+p.pieceId(),p.origin16().cell(),Optional.empty(),Optional.of(data)));}}if(c.before().isEmpty()&&NativeStates.resolve(p).getBlock() instanceof ButtonBlock&&Boolean.parseBoolean(p.sourceState().getOrDefault("powered","false"))){var key="circuit:button:"+p.pieceId();if(!service.effects().containsKey(key)){long due=level.getGameTime()+(p.sourceBlockId().value().equals("minecraft:stone_button")||p.sourceBlockId().value().equals("minecraft:polished_blackstone_button")?20:30);effects.add(new OperationPlan.Effect(key,p.origin16().cell(),Optional.empty(),Optional.of(new BinaryData(Long.toString(due).getBytes(StandardCharsets.UTF_8)))));}}for(String prefix:List.of("circuit:button:","circuit:seed:")){var key=prefix+p.pieceId();var value=service.effects().get(key);if(value!=null&&!value.owner().equals(p.origin16().cell())&&effects.stream().noneMatch(e->e.key().equals(key)))effects.add(new OperationPlan.Effect(key,p.origin16().cell(),Optional.of(value.data()),Optional.of(value.data()),value.owner()));}}
        else if(c.before().isPresent()&&piece(c.before().orElseThrow()))for(String prefix:List.of("circuit:button:","circuit:seed:")){var key=prefix+c.id();var value=service.effects().get(key);if(value!=null&&effects.stream().noneMatch(e->e.key().equals(key)))effects.add(new OperationPlan.Effect(key,value.owner(),Optional.of(value.data()),Optional.empty()));}
    }
        var changedSources=new HashSet<UUID>();for(var c:plan.changes())if(c.after().filter(WorldCircuits::piece).isPresent()){var p=c.after().orElseThrow();if(node(p).kind()==SignalNetwork.Kind.SOURCE&&(c.before().isEmpty()||stateValue(c.before().orElseThrow())!=stateValue(p)))changedSources.add(c.id());}
        if(!changedSources.isEmpty())for(var graph:graphs(after))if(graph.pieces.stream().anyMatch(p->changedSources.contains(p.pieceId()))&&effects.stream().noneMatch(e->e.key().equals("circuit:"+graph.id))){var network=restored(graph);PieceRecord owner=null;for(var p:graph.pieces)if(changedSources.contains(p.pieceId())){network.sourceAt(p.pieceId(),stateValue(p),level.getGameTime());owner=p;}var old=service.effects().get("circuit:"+graph.id);var data=encode(graph,network);var position=owner.origin16().cell();if(old==null||!equivalent(old.data(),data))effects.add(new OperationPlan.Effect("circuit:"+graph.id,position,Optional.ofNullable(old).map(WorldEffectStore.Value::data),Optional.of(data),old==null?position:old.owner()));}
        return new OperationPlan(plan.id(),plan.actor(),plan.kind(),plan.changes(),plan.resourcesBefore(),plan.resourcesAfter(),effects);}
    public void observeNative(net.minecraft.core.BlockPos position){if(observing||service.quarantined()||service.snapshot().ticked(ADAPTER).isEmpty())return;observing=true;try{var cell=new CellPos(position.getX(),position.getY(),position.getZ());var effects=new ArrayList<OperationPlan.Effect>();for(var graph:graphs(service.snapshot())){var affected=graph.inputs.stream().filter(i->SupportPatches.contactCells(i.port.area).cells(8).contains(cell)).toList();if(affected.isEmpty())continue;var network=restored(graph);for(var input:affected)network.sourceAt(input.ghost,input(input),level.getGameTime());var old=service.effects().get("circuit:"+graph.id);var data=encode(graph,network);if(old==null||!equivalent(old.data(),data))effects.add(new OperationPlan.Effect("circuit:"+graph.id,cell,Optional.ofNullable(old).map(WorldEffectStore.Value::data),Optional.of(data),old==null?cell:old.owner()));if(effects.size()==64){service.executeWorld(List.of(),effects);effects.clear();}}service.executeWorld(List.of(),effects);}catch(IOException|RuntimeException ex){if(service.quarantined())NmgRuntime.failed(level,ex);else net.nicomar.nomoregrids.NoMoreGrids.LOGGER.debug("NMG native signal input deferred: {}",ex.toString());}finally{observing=false;}}

    public void tick()throws IOException{
        loadThermal();controls();var graphs=graphs(service.snapshot());var active=new HashSet<String>();for(var g:graphs)active.add("circuit:"+g.id);int processed=0;
        for(int graphIndex=0;graphIndex<Math.min(16,graphs.size());graphIndex++){var g=graphs.get(Math.floorMod(networkCursor++,graphs.size()));if(g.pieces.stream().anyMatch(p->p.worldOccupation().cells(8).stream().anyMatch(c->!ready(c)))){resumeAfter.remove(g.id);continue;}var resumed=resumeAfter.putIfAbsent(g.id,level.getGameTime()+1);if(resumed==null||level.getGameTime()<resumed)continue;var network=restored(g);var oldValues=new HashMap<UUID,Integer>();for(var p:g.pieces)oldValues.put(p.pieceId(),network.value(p.pieceId()));long now=level.getGameTime();for(var p:g.pieces)if(node(p).kind()==SignalNetwork.Kind.SOURCE)network.sourceAt(p.pieceId(),stateValue(p),now);for(var i:g.inputs)network.sourceAt(i.ghost,input(i),now);network.refresh();network.advanceObservable(now,4096,g.pieces.stream().map(PieceRecord::pieceId).collect(java.util.stream.Collectors.toSet()));var owner=g.pieces.getFirst().origin16().cell();var old=service.effects().get("circuit:"+g.id);var data=encode(g,network);var effects=new ArrayList<OperationPlan.Effect>();if(old==null||!equivalent(old.data(),data)||!old.owner().equals(owner))effects.add(new OperationPlan.Effect("circuit:"+g.id,owner,Optional.ofNullable(old).map(WorldEffectStore.Value::data),Optional.of(data),old==null?owner:old.owner()));var changes=new ArrayList<OperationPlan.Change>();thermal(g,network,oldValues,effects);
            for(var p:g.pieces){if(changes.size()==128)break;var values=new HashMap<>(p.sourceState());int value=network.value(p.pieceId());if(node(p).kind()!=SignalNetwork.Kind.SOURCE){if(values.containsKey("power"))values.put("power",Integer.toString(value));else values.put(values.containsKey("lit")?"lit":"powered",Boolean.toString(value>0));}if(values.equals(p.sourceState())&&oldValues.getOrDefault(p.pieceId(),0)==value)continue;changes.add(new OperationPlan.Change(p.pieceId(),Optional.of(p),Optional.of(updated(p,values))));}service.executeWorld(changes,effects);
        }
        var obsolete=new ArrayList<OperationPlan.Effect>();for(var e:service.effectsWithPrefix("circuit:").entrySet())if(e.getKey().matches("circuit:[0-9a-f-]{36}")&&!active.contains(e.getKey())&&discardable(e.getValue().data())&&obsolete.size()<128)obsolete.add(new OperationPlan.Effect(e.getKey(),e.getValue().owner(),Optional.of(e.getValue().data()),Optional.empty()));service.executeWorld(List.of(),obsolete);driveGroups();
    }
    private boolean ready(CellPos c){var pos=WorldService.pos(c);if(!level.isLoaded(pos))return false;if(service.nativeProjection(c).filter(level.getBlockState(pos)::equals).isPresent())return true;return level.getBlockEntity(pos) instanceof CompositeCellEntity cell&&cell.valid()&&cell.view().equals(service.cellView(c,service.snapshot()));}
    private static PieceRecord updated(PieceRecord p,Map<String,String> values){var state=NativeStates.resolve(p.sourceBlockId(),values);var shape=NativeStates.boxes(state.getShape(net.minecraft.world.level.EmptyBlockGetter.INSTANCE,BlockPos.ZERO));var collision=NativeStates.boxes(state.getCollisionShape(net.minecraft.world.level.EmptyBlockGetter.INSTANCE,BlockPos.ZERO));return new PieceRecord(p.pieceId(),Math.incrementExact(p.revision()),p.adapterId(),1,p.sourceBlockId(),values,p.origin16(),p.orientation(),p.pivot16(),new BoxGeometrySnapshot(shape,collision,shape),p.geometryPayload(),p.materialPayload(),p.itemPayload(),p.groupId(),p.flags());}
    private void controls()throws IOException{var controls=service.snapshot().ticked(ADAPTER);for(int turn=0;turn<Math.min(64,controls.size());turn++){var p=controls.get(Math.floorMod(controlCursor++,controls.size()));if(!level.isLoaded(WorldService.pos(p.origin16().cell())))continue;var s=NativeStates.resolve(p);var values=new HashMap<>(p.sourceState());var effects=new ArrayList<OperationPlan.Effect>();String key="circuit:button:"+p.pieceId();var pending=service.effects().get(key);if(s.getBlock() instanceof ButtonBlock&&pending!=null){long due=JsonParser.parseString(new String(pending.data().copy(),StandardCharsets.UTF_8)).getAsLong();if(due<=level.getGameTime()){values.put("powered","false");effects.add(new OperationPlan.Effect(key,pending.owner(),Optional.of(pending.data()),Optional.empty()));}}
            if(s.getBlock() instanceof BasePressurePlateBlock){var b=p.worldOccupation().bounds();var box=new net.minecraft.world.phys.AABB(b.min().x()/16.0,b.min().y()/16.0,b.min().z()/16.0,b.max().x()/16.0,b.max().y()/16.0+0.25,b.max().z()/16.0);int count=level.getEntities((net.minecraft.world.entity.Entity)null,box,e->!e.isSpectator()&&!e.isIgnoringBlockTriggers()).size();if(values.containsKey("power")){int maximum=p.sourceBlockId().value().contains("heavy")?150:15;values.put("power",Integer.toString(Math.min(15,(count*15+maximum-1)/maximum)));}else values.put("powered",Boolean.toString(count>0));}
            if(!values.equals(p.sourceState()))service.executeWorld(List.of(new OperationPlan.Change(p.pieceId(),Optional.of(p),Optional.of(updated(p,values)))),effects);else service.executeWorld(List.of(),effects);
        }}
    public static void use(WorldService service,ServerPlayer player,PieceRecord p)throws IOException{var values=new HashMap<>(p.sourceState());var effects=new ArrayList<OperationPlan.Effect>();var block=NativeStates.resolve(p).getBlock();if(block instanceof LeverBlock)values.put("powered",Boolean.toString(!Boolean.parseBoolean(values.get("powered"))));else if(block instanceof ButtonBlock){if(Boolean.parseBoolean(values.get("powered")))return;values.put("powered","true");var due=new BinaryData(Long.toString(player.level().getGameTime()+(p.sourceBlockId().value().equals("minecraft:stone_button")||p.sourceBlockId().value().equals("minecraft:polished_blackstone_button")?20:30)).getBytes(StandardCharsets.UTF_8));var key="circuit:button:"+p.pieceId();var old=service.effects().get(key);effects.add(new OperationPlan.Effect(key,p.origin16().cell(),Optional.ofNullable(old).map(WorldEffectStore.Value::data),Optional.of(due)));}else if(block instanceof RepeaterBlock)values.put("delay",Integer.toString(Integer.parseInt(values.get("delay"))%4+1));else if(block instanceof ComparatorBlock)values.put("mode","subtract".equals(values.get("mode"))?"compare":"subtract");else return;var inventory=NativeInventory.encode(player,NativeInventory.copy(player));service.executePrepared(new OperationPlan(UUID.randomUUID(),player.getUUID(),OperationPlan.Kind.EDIT,List.of(new OperationPlan.Change(p.pieceId(),Optional.of(p),Optional.of(updated(p,values)))),inventory,inventory,effects));}
    public static int output(BlockGetter world,BlockPos pos,Direction direction){if(!(world.getBlockEntity(pos) instanceof CompositeCellEntity cell)||!cell.valid())return 0;int value=0;var outward=Direction6.valueOf(direction.getOpposite().name());long axis=outward.axis()==0?pos.getX():outward.axis()==1?pos.getY():pos.getZ();long u=outward.axis()==0?pos.getZ()*16L:pos.getX()*16L,v=outward.axis()==1?pos.getZ()*16L:pos.getY()*16L;var nativePort=new Port(new UUID(0,0),outward.opposite(),new SupportResolver.Patch(outward.opposite(),(axis+(outward.sign()>0?1:0))*16,u,v,u+16,v+16),false,SignalNetwork.Input.REAR,false);for(var p:cell.view().replicas())if((piece(p)||WorldRails.detector(p))&&!p.flags().contains(PieceRecord.Flag.SUBSTITUTE))for(var port:ports(p))if(port.output&&matches(port,nativePort)){int n=stateValue(p);if(world instanceof ServerLevel level&&NmgRuntime.existing(level)!=null)n=WorldRails.detector(p)?stateValue(p):NmgRuntime.existing(level).circuits().value(p);value=Math.max(value,n);}return value;}
    public int power(PieceRecord target){
        int power=0;var index=service.snapshot();
        for(var d:Direction6.values()){
            var area=SupportPatches.transform(new SupportResolver.Patch(d,d.sign()>0?16:0,0,0,16,16),target);
            var input=new Port(target.pieceId(),area.normal(),area,false,SignalNetwork.Input.REAR,false);
            var contacts=SupportPatches.contactCells(area).cells(8);var candidates=new HashSet<UUID>();
            // A port and its piece's occupation lie inside the same transformed
            // one-block envelope. One surrounding cell reaches every matching port.
            for(var c:contacts)for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)candidates.addAll(index.at(new CellPos(c.x()+x,c.y()+y,c.z()+z)));
            for(var id:candidates){var p=index.records().get(id);if(piece(p)||WorldRails.detector(p))for(var output:ports(p))if(output.output&&matches(output,input))power=Math.max(power,value(p));}
            for(var c:contacts){var pos=WorldService.pos(c);if(!level.isLoaded(pos)||!index.at(c).isEmpty())continue;long plane=(area.normal().axis()==0?c.x():area.normal().axis()==1?c.y():c.z())*16+(area.normal().sign()<0?16:0);if(plane==area.plane())power=Math.max(power,level.getSignal(pos,Direction.valueOf(area.normal().name())));}
        }return power;
    }
    private void driveGroups()throws IOException{var groups=service.snapshot().ticked(WorldGroups.ADAPTER).stream().filter(p->p.sourceState().containsKey("open")).toList();for(int turn=0;turn<Math.min(16,groups.size());turn++){var p=groups.get(Math.floorMod(groupCursor++,groups.size()));if(p.worldOccupation().cells(8).stream().anyMatch(c->!level.isLoaded(WorldService.pos(c))))continue;int power=power(p);boolean powered=power>0;if(powered!=Boolean.parseBoolean(p.sourceState().get("powered")))WorldGroups.setOpen(service,null,p,powered,powered);}}
}
